<script lang="ts">
 import {zh} from './zh';
 import {engine,type ScorePanels} from '../../bridge/engine.svelte';import AriaSymbol from './AriaSymbol.svelte';import AriaFader from './AriaFader.svelte';
 let {phone,title,onclose,onerror}:{phone:boolean;title:string;onclose:()=>void;onerror:(message:string)=>void}=$props();
 let data=$state<ScorePanels>(engine.scorePanels()),width=$state(900);
 $effect(()=>{if(engine.status!=='ready')return;engine.composerState({metering:true});return()=>{if(engine.status==='ready')engine.composerState({metering:false});};});
 const channels=$derived([...data.channels.filter(c=>c.id===-1),...data.channels.filter(c=>c.id!==-1&&c.name!=='节拍器')]);
 const channelWidth=$derived(phone?Math.min(108,Math.max(98,width*.27)):Math.min(176,Math.max(138,(width-32)/Math.min(channels.length,6))));
 const colors=['#007aff','#30b0c7','#ff9500','#ff2d55','#af52de','#ffcc00','#5856d6','#34c759','#32ade6'];
 function mix(id:number,key:string,value:number|boolean){const result=engine.changeMixer({id,[key]:value});if(!result.ok)onerror('Mix could not be changed.');data=engine.scorePanels();}
 function reset(){for(const channel of channels)engine.changeMixer({id:channel.id,volume:0,pan:0,muted:false,solo:false});data=engine.scorePanels();}
 const volume=(db:number)=>db<=-60?0:Math.pow(10,db/20);
 const panLabel=(v:number)=>Math.abs(v)<.01?'居中':Math.round(Math.abs(v)*100)+'% '+(v<0?'左':'右');
</script>
<div class="aria-mixer" class:phone bind:clientWidth={width}>
 <header><AriaSymbol name="waveform" size={phone?22:28}/><div><h2>混音器</h2><small>{data.parts.length} 件乐器{!phone?' · '+title:''}</small></div><button class="reset" onclick={reset}><AriaSymbol name="arrow.counterclockwise" size={16}/>{phone?'重置':'重置混音'}</button><button class="close" aria-label="关闭混音器" onclick={onclose}><AriaSymbol name="xmark" size={phone?13:14}/></button></header>
 <div class="strips">{#each channels as channel,index}{@const name=channel.id===-1?'总输出':channel.name}{@const color=colors[index%colors.length]}{#if index===1}<div class="master-divider"></div>{/if}<section class="channel" style:width={channelWidth+'px'} style:--channel-color={color}><h3><span></span>{name}</h3><div class="mute-solo"><button class:active={channel.muted} class:mute={channel.muted} aria-label={zh('Mute '+name)} aria-pressed={channel.muted} onclick={()=>mix(channel.id,'muted',!channel.muted)}>静音</button>{#if channel.id!==-1}<button class:active={channel.solo} aria-label={zh('Solo '+name)} aria-pressed={channel.solo} onclick={()=>mix(channel.id,'solo',!channel.solo)}>独奏</button>{:else}<span></span>{/if}</div><div class="fader-row"><AriaFader value={volume(channel.volume)} {color} compact={phone} label={name+' 音量'} onchange={v=>mix(channel.id,'volume',v<.0001?-60:20*Math.log10(v))}/><div class="stereo-meter" aria-hidden="true"><span><i style:height={(engine.playing?(engine.mixerLevels[channel.id]||0)*100:0)+'%'}></i></span><span><i style:height={(engine.playing?(engine.mixerLevels[channel.id]||0)*94:0)+'%'}></i></span></div></div><div class="decibels">{channel.volume<=-60?'−∞':channel.volume.toFixed(1)} dB</div><div class="pan"><input type="range" min="-1" max="1" step=".01" value={channel.pan} aria-label={zh(name+' 声像')} aria-valuetext={panLabel(channel.pan)} oninput={e=>mix(channel.id,'pan',Number(e.currentTarget.value))}/><div><span>L</span><button aria-label={zh('Center '+name+' 声像')} onclick={()=>mix(channel.id,'pan',0)}><i></i></button><span>R</span></div></div></section>{/each}</div>
</div>
<style>
 .aria-mixer{height:100%;display:flex;flex-direction:column;}.aria-mixer header{display:flex;align-items:center;gap:14px;padding:8px 24px 10px;border-bottom:.5px solid #0002;color:#007aff;}.aria-mixer header>div{flex:1;min-width:0;color:#000d;}.aria-mixer h2{font-size:22px;}.aria-mixer header small{font-size:14px;color:#0008;white-space:nowrap;}.aria-mixer header button{border:0;background:none;color:#007aff;min-height:44px;display:flex;gap:6px;align-items:center;font-size:14px;font-weight:500;}.aria-mixer header .close{width:34px;height:34px;min-height:34px;display:grid;place-items:center;border-radius:50%;background:#007aff1a;outline:1px solid #007aff1f;}.strips{display:flex;align-items:start;overflow-x:auto;gap:10px;padding:10px 16px;flex:1;min-height:0;scrollbar-width:none;}.channel{flex:none;padding:12px 14px;display:flex;flex-direction:column;align-items:center;gap:8px;background:#ffffffdf;border:1px solid #00000012;border-radius:16px;}.channel h3{display:flex;align-items:center;gap:9px;width:100%;font-size:14px;font-weight:600;white-space:nowrap;overflow:hidden;}.channel h3 span{width:13px;height:13px;background:var(--channel-color);flex:none;border-radius:50%;}.mute-solo{display:flex;gap:8px;align-items:center;min-height:36px;}.mute-solo button,.mute-solo>span{width:46px;height:32px;min-height:0;border-radius:8px;border:0;background:#00000012;font-size:14px;font-weight:600;}.mute-solo>span{visibility:hidden;}.mute-solo .active{background:#007aff;color:white;}.mute-solo .mute{background:#ff3b30;}.fader-row{height:138px;display:flex;align-items:center;gap:12px;}.stereo-meter{display:flex;gap:3px;width:11px;height:100%;}.stereo-meter>span{width:4px;height:100%;border-radius:2px;background:#00000029;}.stereo-meter>span{position:relative;overflow:hidden;}.stereo-meter i{position:absolute;inset:auto 0 0;display:block;background:linear-gradient(to top,#34c759,#00c7be,#ffcc00);transition:height .05s linear;}.decibels{font-size:14px;font-variant-numeric:tabular-nums;}.pan{width:100%;}.pan input{width:100%;accent-color:#888;}.pan>div{display:flex;align-items:center;justify-content:space-between;font-size:10px;color:#0008;}.pan button{border:0;background:none;width:30px;height:14px;min-height:0;display:grid;place-items:center;}.pan i{width:7px;height:2px;border-radius:1px;background:#0007;}.master-divider{width:1px;height:300px;flex:none;background:#0002;margin:0 4px;}.phone header{gap:12px;padding:6px 8px 6px 14px;}.phone h2{font-size:17px;}.phone header small{font-size:12px;}.phone header .close{width:32px;height:32px;}.phone .strips{padding:6px 10px;gap:7px;scroll-snap-type:x proximity;}.phone .channel{padding:7px 8px;gap:4px;border-radius:13px;scroll-snap-align:start;}.phone .channel h3{font-size:12px;gap:6px;}.phone .channel h3 span{width:10px;height:10px;}.phone .mute-solo{gap:5px;min-height:32px;}.phone .mute-solo button,.phone .mute-solo>span{width:34px;height:28px;font-size:12px;}.phone .fader-row{height:92px;gap:8px;}.phone .decibels{font-size:12px;}.phone .master-divider{height:220px;margin:0;}
</style>
